import{_ as o,o as e,c as s,af as a}from"./chunks/framework.Dt3O48XQ.js";const g=JSON.parse('{"title":"人数压力测","description":"","frontmatter":{},"headers":[],"relativePath":"ops/load-testing.md","filePath":"ops/load-testing.md","lastUpdated":null}'),d={name:"ops/load-testing.md"};function n(r,t,i,l,c,h){return e(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="人数压力测" tabindex="-1">人数压力测 <a class="header-anchor" href="#人数压力测" aria-label="Permalink to &quot;人数压力测&quot;">​</a></h1><p>使用 <strong><code>loadtest_room</code></strong> 与仓库内 <strong><code>loadtest/</code></strong> 脚本，可在可控环境验证 <strong>并发连接数</strong>、进房延迟与消息往返，适合部署前容量摸底或回归对比。<strong>生产环境务必关闭压测房或限制访问，勿省略 <code>LOADTEST_ROOM_ENABLED</code> 等开关。</strong></p><h2 id="压测房间说明" tabindex="-1">压测房间说明 <a class="header-anchor" href="#压测房间说明" aria-label="Permalink to &quot;压测房间说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>房间名</td><td><code>loadtest_room</code>，对应服务端 <code>LoadTestRoom</code></td></tr><tr><td>鉴权</td><td><strong>无需 JWT</strong>，仅用于压连接与吞吐；业务房间不可照搬此模式</td></tr><tr><td>开关</td><td>环境变量 <strong><code>LOADTEST_ROOM_ENABLED</code></strong>：设为 <strong><code>false</code></strong> 时创建房间会直接报错，便于生产关闭</td></tr><tr><td>单房人数上限</td><td><strong><code>LOADTEST_ROOM_MAX_CLIENTS</code></strong>（默认上限裁剪后为较大值，仍在 1～65535）</td></tr></tbody></table><p>房间内维护 Schema 状态 <strong><code>connectedCount</code></strong> / <strong><code>revision</code></strong>；支持消息 <strong><code>load</code></strong>（负载字段 <code>n</code>、<code>clientSeq</code>），服务端回复 <strong><code>loadAck</code></strong>（含 <code>serverTime</code>）。可用于周期性打点观察延迟。</p><p>详见服务端：<code>src/rooms/LoadTestRoom.ts</code>、<code>src/rooms/schema/LoadTestRoomState.ts</code>。</p><h2 id="推荐运行方式-node-脚本" tabindex="-1">推荐运行方式（Node 脚本） <a class="header-anchor" href="#推荐运行方式-node-脚本" aria-label="Permalink to &quot;推荐运行方式（Node 脚本）&quot;">​</a></h2><p>脚本路径：<strong>仓库根目录</strong> <code>loadtest/concurrent-join.ts</code>。在项目根执行（需已安装依赖、<code>tsx</code> 可用）：</p><p><strong>（服务端代码）</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> loadtest/concurrent-join.ts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --endpoint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:2567</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --room</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> loadtest_room</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --num</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 500</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --delay</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 15</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --sendInterval</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 150</span></span></code></pre></div><p>常用参数：</p><table tabindex="0"><thead><tr><th>参数</th><th>含义</th></tr></thead><tbody><tr><td><code>--endpoint</code></td><td>Colyseus HTTP 入口（与浏览器访问同源）</td></tr><tr><td><code>--room</code></td><td>房间名；压测房填 <strong><code>loadtest_room</code></strong></td></tr><tr><td><code>--num</code></td><td>模拟客户端数量</td></tr><tr><td><code>--delay</code></td><td>相邻两次 join 之间的间隔（毫秒），减轻瞬时洪峰</td></tr><tr><td><code>--sendInterval</code></td><td>周期性发送 <code>load</code> 消息的间隔（毫秒），<strong>0</strong> 表示只连不发</td></tr><tr><td><code>--timeout</code></td><td>单次 join 超时（毫秒）</td></tr></tbody></table><p>脚本注释中的示例（与仓库一致）：</p><p><strong>（服务端代码）</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npx tsx loadtest/concurrent-join.ts --endpoint http://127.0.0.1:2567 --room loadtest_room --num 500 --delay 15 --sendInterval 150</span></span></code></pre></div><h3 id="带-jwt-的并发-业务房间" tabindex="-1">带 JWT 的并发（业务房间） <a class="header-anchor" href="#带-jwt-的并发-业务房间" aria-label="Permalink to &quot;带 JWT 的并发（业务房间）&quot;">​</a></h3><p>若要对 <strong><code>chat_world_room</code></strong> 等需鉴权的房间压人数，需传入有效 JWT：</p><p><strong>（服务端代码）</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>npx tsx loadtest/concurrent-join.ts --room chat_world_room --num 200 --token &lt;JWT&gt;</span></span></code></pre></div><p>可选：<code>--guildId</code>、<code>--teamId</code>（与 <a href="/xcs.github.io/reference/protocol.html">消息协议</a> 进房参数一致）。</p><h2 id="部署与环境变量" tabindex="-1">部署与环境变量 <a class="header-anchor" href="#部署与环境变量" aria-label="Permalink to &quot;部署与环境变量&quot;">​</a></h2><ul><li><strong>生产</strong>：建议 <strong><code>LOADTEST_ROOM_ENABLED=false</code></strong>，或通过网络策略禁止外网访问压测房。</li><li><strong>单机摸底</strong>：在隔离环境开启压测房，结合 <strong><code>LOADTEST_ROOM_MAX_CLIENTS</code></strong> 与机器 CPU / 内存 / 文件句柄上限逐步加压。</li><li><strong>观测</strong>：关注进程 CPU、事件循环延迟、WebSocket 连接数、Redis/MySQL（若业务路径会打到）；必要时对照 <a href="/xcs.github.io/ops/deployment.html">部署说明</a> 做多实例与网关限制规划。</li></ul><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/xcs.github.io/guide/project-structure.html">项目结构</a>（<code>loadtest/</code>、<code>loadtest_room</code> 索引）</li><li><a href="/xcs.github.io/guide/jwt-room-auth.html">JWT 与房间鉴权</a>（压测房与业务房鉴权差异）</li><li><a href="/xcs.github.io/scenarios/overview.html">应用场景</a>（压测在整体能力中的位置）</li></ul>',24)])])}const k=o(d,[["render",n]]);export{g as __pageData,k as default};
